css.value:
var(--group-surface-overlay-flex-none) var(--group-surface-overlay-flex-none)
    min(
      var(--group-surface-overlay-sheet-width),
      calc(
        var(--group-surface-overlay-size-flex-100vw) - 2 * var(--group-surface-overlay-chrome-inset)
      )
    )

linear-gradient(
        var(--group-trigger-button-color-content-primary) var(--group-trigger-button-number-0)
          var(--group-trigger-button-number-0)
      )
      content-box,
    linear-gradient(
      var(--group-trigger-button-color-content-primary) var(--group-trigger-button-number-0)
        var(--group-trigger-button-number-0)
    )

inset var(--group-trigger-button-number-0) var(--group-trigger-button-number-0)
    var(--group-trigger-button-number-0) var(--group-trigger-button-state-overlay-spread)
    color-mix(
      in srgb,
      var(--group-trigger-button-intent-fg) var(--group-trigger-button-state-overlay-hover),
      transparent
    )

inset var(--group-trigger-button-number-0) var(--group-trigger-button-number-0)
    var(--group-trigger-button-number-0) var(--group-trigger-button-state-overlay-spread)
    color-mix(
      in srgb,
      var(--group-trigger-button-intent-fg) var(--group-trigger-button-state-overlay-pressed),
      transparent
    )

inset var(--group-trigger-button-number-0) var(--group-trigger-button-number-0)
    var(--group-trigger-button-number-0) var(--group-trigger-button-state-overlay-spread)
    color-mix(
      in srgb,
      var(--group-trigger-button-color-surface-surface)
        var(--group-trigger-button-state-overlay-hover),
      transparent
    )

inset var(--group-trigger-button-number-0) var(--group-trigger-button-number-0)
    var(--group-trigger-button-number-0) var(--group-trigger-button-state-overlay-spread)
    color-mix(
      in srgb,
      var(--group-trigger-button-color-surface-surface)
        var(--group-trigger-button-state-overlay-pressed),
      transparent
    )

linear-gradient(
    to right,
    transparent,
    var(--group-navigation-color-content-primary)
      var(--group-navigation-size-mask-image-micro-regular),
    var(--group-navigation-color-content-primary)
      calc(
        var(--group-navigation-size-mask-image-full) -
          var(--group-navigation-size-mask-image-micro-regular)
      ),
    transparent
  )

linear-gradient(
    var(--group-feedback-skeleton-angle-90deg),
    transparent,
    color-mix(
      in srgb,
      var(--group-feedback-skeleton-color-surface-surface) var(--group-feedback-skeleton-mix-60),
      transparent
    ),
    transparent
  )

color-mix(
    in srgb,
    var(--group-surface-color-scrim) var(--group-surface-mix-70),
    transparent
  )

light-dark(
    color-mix(
      in srgb,
      var(--group-trigger-button-intent-fg) var(--group-trigger-button-tertiary-foreground-hover),
      var(--group-trigger-button-color-content-primary)
    ),
    var(--group-trigger-button-intent-fg)
  )
